BEGIN TRANSACTION;
CREATE TABLE crop (station_id,year,plant_day,plant_length,rain_total,include_start_condition,summary_type,summary_element,summary_value,definition_id,status,time_stamp);
CREATE TABLE definition (definition_id,time_stamp,summary_element,summary_type,definition_value,accreditation);
CREATE TABLE station (station_id,station_name,latitude,longitude,elevation,district,country_code,time_stamp,status);
CREATE TABLE summary (station_id,definition_id,time_type,time_value,summary_type,summary_element,summary_name,summary_value,time_stamp,status);
CREATE TABLE summary_station_metadata (station_id,summary_type,definition_id,time_stamp);
COMMIT;